/// <summary>
/// CB788_CustomPricingComponents
/// Price component detail table
/// </summary>
public class METSalesLinePriceComponentDetail extends common
{
}

Method.Source:
/// <summary>
/// Simulates what is done in GUPDiscountHelper\distributeDiscountClaim
/// with GUPDiscountClaimDistribution.isClaimDistribution()
/// </summary>
/// <returns>always true for us as we will always claim</returns>
public boolean isClaimDistribution()
{
    return true;
}

/// <summary>
/// Display method to show price code reference in the price component detail grid
/// </summary>
/// <returns>Price component price code reference</returns>
[SysClientCacheDataMethodAttribute(true)]
display METPriceCodeRef priceCodeRef()
{
    return this.salesLinePriceComponent().PriceCodeRef;
}

/// <summary>
/// Retrieve price component from price component details InventTransId and Component
/// </summary>
/// <param name = "_forUpdate">Specifies if record is selected for update</param>
/// <returns>Found price component record; otherwise, blank.</returns>
METSalesLinePriceComponent salesLinePriceComponent(boolean _forUpdate = false)
{
    return METSalesLinePriceComponent::find(this.InventTransId, this.Component, _forUpdate);
}

    /// <summary>
    /// Find a price component detail record
    /// </summary>
    /// <param name = "_inventTransId">The <c>InventTransId</c> value to retrieve the price component detail record.</param>
    /// <param name = "_component">The <c>METComponent</c> value to retrieve the price component detail record.</param>
    /// <param name = "_code">The <c>METComponentCodeId</c> value to retrieve the price component detail record.</param>
    /// <param name = "_forUpdate">Specifies if record is selected for update</param>
    /// <returns>Found price component detail record; otherwise, blank.</returns>
    static METSalesLinePriceComponentDetail find(InventTransId      _inventTransId,
                                                 METComponent       _component,
                                                 METComponentCodeId _code,
                                                 boolean            _forUpdate = false)
    {
        METSalesLinePriceComponentDetail priceComponentDetail;

        if (_inventTransId && _component && _code)
        {
            if (_forUpdate)
            {
                priceComponentDetail.selectForUpdate(_forUpdate);
            }

            select firstonly priceComponentDetail
                       where priceComponentDetail.InventTransId == _inventTransId
                          && priceComponentDetail.Component     == _component
                          && priceComponentDetail.Code          == _code;
        }

        return priceComponentDetail;
    }

/// <summary>
///    Checks whether a price component detail record exists.
/// </summary>
/// <param name="_inventTransId">
///    The <c>InventTransId</c> value to retrieve the price component detail record.
/// </param>
/// <param name="_component">
///    The <c>METComponent</c> value to retrieve the price component detail record.
/// </param>
/// <param name="_code">
///    The <c>METComponentCodeId</c> value to retrieve the price component detail record.
/// </param>
/// <returns>
///    true if the price component detail record exists; otherwise, false.
/// </returns>
static boolean exist(InventTransId _inventTransId, METComponent _component, METComponentCodeId _code)
{
    return _inventTransId &&
           _component &&
           _code &&
           (select firstonly RecId from METSalesLinePriceComponentDetail
                                  where METSalesLinePriceComponentDetail.InventTransId == _inventTransId
                                     && METSalesLinePriceComponentDetail.Component == _component
                                     && METSalesLinePriceComponentDetail.Code == _code).RecId != 0;
}
